fixed_edges = [(2,6), (5,7), (2,5), (1,2), (4,6), (3,6), (1,5)]

# Build adjacency
adj = {i: set() for i in range(9)}
for u,v in fixed_edges:
    adj[u].add(v)
    adj[v].add(u)

# Find connected components
visited = set()
components = []
for v in range(9):
    if v not in visited:
        stack = [v]
        comp = set()
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                comp.add(node)
                for nb in adj[node]:
                    if nb not in visited:
                        stack.append(nb)
        components.append(comp)

print("Components:", components)
print("Number of components:", len(components))
